/**
 * 改造自 shadcn 原装 base-lyra badge（https://ui.shadcn.com/r/styles/base-lyra/badge.json，MIT）。
 * 与上游的差异：
 * 1. 动效改由 `motion` 属性选预设（ADR 0021），缺省 `none`（与上游一致）。
 *    `pulse`：徽标渲染 `data-motion="pulse"`，整块呼吸，表示「仍在进行」。
 *    `swap`：内容包进一层 `data-motion="swap"` 的 span，以 `contentKey`（缺省取字符串或数字的 children）为 key；
 *    内容一变就重挂，从下方滚入。徽标本身的 `overflow-hidden` 裁掉滚入的部分。
 * 2. 不导出 `badgeVariants`：cva 不是公开 API（SKILL 第 5 步），本系统里没有调用处。
 * 此外只有格式化与一条 Biome 豁免注释，其余类名逐字保留。
 */
import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import type * as React from "react";

/**
 * 徽标支持的动效预设（ADR 0021）。缺省 `none`。
 * - `none`：不动。一般的状态、计数。
 * - `pulse`：不透明度 1 → 0.5 → 1 呼吸，2s 循环。状态是「进行中」。
 * - `swap`：内容变化时从下方滚入（位移 85%、缩放 94%、模糊 6px），340ms。会变的计数、状态。
 */
type BadgeMotion = "none" | "pulse" | "swap";

const badgeVariants = cva(
  // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的焦点环。
  "group/badge inline-flex h-5 w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-none border border-transparent px-2 py-0.5 text-xs font-medium whitespace-nowrap transition-all focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&>svg]:size-3!",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground [a]:hover:bg-primary/80",
        secondary: "bg-secondary text-secondary-foreground [a]:hover:bg-secondary/80",
        destructive:
          "bg-destructive/10 text-destructive focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:focus-visible:ring-destructive/40 [a]:hover:bg-destructive/20",
        outline: "border-border text-foreground [a]:hover:bg-muted [a]:hover:text-muted-foreground",
        ghost: "hover:bg-muted hover:text-muted-foreground dark:hover:bg-muted/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

/** swap 的重挂 key：显式的 contentKey 优先，否则取字符串或数字的 children。 */
function swapKeyOf(contentKey: React.Key | undefined, children: React.ReactNode): React.Key | null {
  if (contentKey !== undefined) return contentKey;
  return typeof children === "string" || typeof children === "number" ? children : null;
}

function Badge({
  className,
  variant = "default",
  motion = "none",
  contentKey,
  children,
  render,
  ...props
}: useRender.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    motion?: BadgeMotion;
    /** `motion="swap"` 时的内容标识：变化即重播滚入。缺省取字符串或数字的 children。 */
    contentKey?: React.Key;
  }) {
  const content =
    motion === "swap" ? (
      <span
        key={swapKeyOf(contentKey, children)}
        data-slot="badge-content"
        data-motion="swap"
        className="inline-flex items-center gap-1 [&>svg]:pointer-events-none [&>svg]:size-3!"
      >
        {children}
      </span>
    ) : (
      children
    );
  // data-* 不在 span 的属性类型里，先放进变量再合并（对象字面量会触发多余属性检查）。
  const ownProps = {
    className: cn(badgeVariants({ variant }), className),
    children: content,
    "data-motion": motion === "pulse" ? "pulse" : undefined,
  };
  return useRender({
    defaultTagName: "span",
    props: mergeProps<"span">(ownProps, props),
    render,
    state: {
      slot: "badge",
      variant,
    },
  });
}

export { Badge, type BadgeMotion };
